// Builds a serpentine (weaving) pre-computed path for a missile unit, used by skills like Guided Arrow. Caps the path at 0x4D frames, sets path type 10, then for each frame advances the direction by a randomly-seeded amplitude and sign (flipping every gapSkillDamageDescFuncTable[0x89] frames), samples gnSkillSynergiesTableIndex/Offset for X/Y deltas, and writes each resulting (nX, nY) into the missile's path-point array via GetPathPoint.
void __fastcall SKILLSCLT_SetMissilePathExtended(D2UnitStrc * pUnit, int32_t nInitSeed) {
    // Static local variables (originally global data)
    static int gnSkillSynergiesTableOffset[8] = { 0x0, 0x2, 0x2, 0x2, 0x0, -0x2, -0x2, -0x2 }; D2_STATIC_GUARD(gnSkillSynergiesTableOffset, "D2Client::SKILLS::SKILLSCLT_SetMissilePathExtended::gnSkillSynergiesTableOffset");
    static int gnSkillSynergiesTableIndex[8] = { 0x2, 0x2, 0x0, -0x2, -0x2, -0x2, 0x0, 0x2 }; D2_STATIC_GUARD(gnSkillSynergiesTableIndex, "D2Client::SKILLS::SKILLSCLT_SetMissilePathExtended::gnSkillSynergiesTableIndex");
    static int32_t gnSkillDescLayoutPos_0072d98c = 0xf; D2_STATIC_GUARD(gnSkillDescLayoutPos_0072d98c, "D2Client::SKILLS::SKILLSCLT_SetMissilePathExtended::gnSkillDescLayoutPos_0072d98c");
    static int32_t gnSkillDescLayoutPos_0072d990 = 0x2; D2_STATIC_GUARD(gnSkillDescLayoutPos_0072d990, "D2Client::SKILLS::SKILLSCLT_SetMissilePathExtended::gnSkillDescLayoutPos_0072d990");

    int nSerpentineSign;
    int nPathFrameIdx;
    int32_t nSerpentineAmp;
    D2PathPointStrc* pPathPoints;
    int32_t nCurY;
    int32_t nCurX;
    D2SeedStrc sSeedNext;
    uint64_t ullSeedTemp;
    if (!pUnit) {
      return;
    }

    int32_t nTotalFrames = D2Common::Units::Missile::GetTotalFrames(pUnit);
    if (nTotalFrames >= 0x4e) {
      nTotalFrames = 0x4d;
      D2Common::Units::Missile::SetTotalFrames(pUnit, 0x4d);
      D2Common::Units::Missile::SetCurrentFrame(pUnit, 0x4d);
    }

    D2DynamicPathStrc* pDynamicPath = pUnit->pPath.pDynamicPath;
    D2SeedStrc* pSeed = &pUnit->sSeed;
    D2Common::Seed::InitSeed_Param_666(pSeed, nInitSeed);
    D2Common::PATH::DynamicPath::PATH_SetPathType(pDynamicPath, 10);
    D2Common::PATH::DynamicPath::OverwriteDistanceAndMaxDistance(pDynamicPath, (uint8_t)nTotalFrames);
    D2Common::PATH::DynamicPath::GetPathPoint(pDynamicPath, &pPathPoints);
    eD2UnitType eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nCurX = pUnit->pPath.pStaticPath->nPosX;
    } else if (pUnit->pPath.pDynamicPath) {
      nCurX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
    } else {
      nCurX = 0;
    }

    eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nCurY = pUnit->pPath.pStaticPath->nPosY;
    } else if (pUnit->pPath.pDynamicPath) {
      nCurY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
    } else {
      nCurY = 0;
    }

    uint32_t nSP1Y = D2Common::PATH::DynamicPath::GetYSP1(pUnit->pPath.pDynamicPath);
    uint32_t nCurDir = D2Common::Units::GetDirectionToCoords(pUnit, D2Common::PATH::DynamicPath::GetXSP1(pUnit->pPath.pDynamicPath), nSP1Y);
    nCurDir &= 0xff;
    ullSeedTemp = (uint64_t)pSeed->nSeedLow * 0x6ac690c5 + (uint64_t)pUnit->sSeed.nSeedHigh;
    nSerpentineSign = ullSeedTemp & 1 ? 0x1 : -0x1;
    sSeedNext = D2_SEED_NEXT_VAL(ullSeedTemp);
    *pSeed = sSeedNext;
    nSerpentineAmp = sSeedNext.nSeedLow % 3 + gnSkillDescLayoutPos_0072d990;
    nPathFrameIdx = 0;
    if (nTotalFrames > 0) {
      uint8_t bVar1;
      do {
        nCurDir += nSerpentineAmp * nSerpentineSign;
        bVar1 = D2Common::Monsters::MONSTERS::MONSTERS_GetGfxOffsetTable2((uint8_t)nCurDir & 0x3f);
        nCurX += gnSkillSynergiesTableIndex[bVar1];
        nCurY += gnSkillSynergiesTableOffset[bVar1];
        pPathPoints[nPathFrameIdx].nX = (uint16_t)nCurX;
        pPathPoints[nPathFrameIdx].nY = (uint16_t)nCurY;
        if (!(nPathFrameIdx % gnSkillDescLayoutPos_0072d98c)) {
          nSerpentineSign = -nSerpentineSign;
          sSeedNext = D2_SEED_NEXT(*pSeed);
          *pSeed = sSeedNext;
          nSerpentineAmp = sSeedNext.nSeedLow % 3 + gnSkillDescLayoutPos_0072d990;
        }

        nPathFrameIdx++;
      } while (nPathFrameIdx < nTotalFrames);
    }

    D2Common::PATH::DynamicPath::SetPathPointsSize(pDynamicPath, nTotalFrames);
}

