BOOL __fastcall Skills_CltDoFunc_AuraLevel_MissilesOnTargetVelocity(D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount && sgptDataTable->pTxtSkills + eSkill)) {
      return 0;
    }

    eMissilesId eMissileId = SkillsAss::SKILLSASS_GetCltMissileByAuraLevel(pUnit, eSkill);
    if ((int)eMissileId < 0) {
      return 0;
    }

    D2UnitStrc* pTargetUnit = UNIT::CUnit::GetConfirmedTargetUnit(pUnit);
    if (!pTargetUnit) {
      return 0;
    }

    int32_t nVelocity = D2Common::DATATBLS::MissileTbls::MISSILETBLS_CalculateVelocity(eMissileId, nSkillLvl);
    Skills::SKILL_SpawnMissilesAtTarget(pUnit, pTargetUnit, eMissileId, ~MISSILE_Arrow, eSkill, nSkillLvl, nVelocity);
    return 1;
}

BOOL __fastcall Skills_CltDoFunc_AuraLevel_CltCreateMissileAtTarget(D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    D2SkillsTxt* pSkillTxt = (int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount ? sgptDataTable->pTxtSkills + eSkill : nullptr;
    if (!pSkillTxt) {
      return 0;
    }

    uint32_t nMissileId = SkillsAss::SKILLSASS_GetCltMissileByAuraLevel(pUnit, eSkill);
    if ((int)nMissileId < 0) {
      return 0;
    }

    D2UnitStrc* pTargetUnit = UNIT::CUnit::GetConfirmedTargetUnit(pUnit);
    if (!pTargetUnit) {
      return 0;
    }

    uint32_t nPrgCalc = SkillsAss::SKILLSASS_GetPrgCalcByAuraLevel(pUnit, eSkill, nSkillLvl);
    if ((int)nPrgCalc <= 0) {
      nPrgCalc = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillTxt->aurarangecalc, eSkill, nSkillLvl);
    }

    uint32_t pOwnerUnit = pUnit->nInitSeed;
    int32_t nTargetX = Units::GetXPosFromDynamicPathUnit(pTargetUnit);
    int32_t nTargetY = Units::GetYPosFromDynamicPathUnit(pTargetUnit);
    SKILLSCLT_CltCreateMissileAtTarget(nMissileId, pOwnerUnit, pUnit, (uint8_t*)nMissileId, nTargetX, nTargetY, nSkillLvl, nPrgCalc, eSkill);
    return 1;
}

